#include "common/benchmark.hpp"
#include "cfd/multiphysics/electro_thermal.hpp"
#include "cfd/fem/mesh2d.hpp"
#include <algorithm>
int main(int argc,char**argv){using namespace cfd::examples;const auto o=parse_options(argc,argv);const std::size_t nx=o.quick?6U:48U*o.scale,ny=o.quick?4U:24U*o.scale,steps=o.quick?2U:80U;using Type=cfd::fem::ScalarBoundaryType;Timer setup;auto mesh=cfd::fem::make_rectangle_tri_mesh(nx,ny,2.0,1.0);cfd::fem::Heat2DConfig thermal;thermal.conductivity=1.0;thermal.volumetric_heat_capacity=2.0;thermal.dt=2e-3;cfd::multiphysics::JouleHeatingCoupler2D c(std::move(mesh),thermal);c.set_electrical_boundary(0,{Type::dirichlet,[](cfd::fem::Node2){return 0.0;},{}});c.set_electrical_boundary(1,{Type::dirichlet,[](cfd::fem::Node2){return 4.0;},{}});c.initialize_temperature([](cfd::fem::Node2){return 300.0;});c.set_thermal_dirichlet([](cfd::fem::Node2,double){return 300.0;});const double setup_ms=setup.milliseconds();Timer sim;c.solve_electrical([](cfd::fem::Node2){return 5.0;});c.thermal_run(steps);const double sim_ms=sim.milliseconds();const double max_t=*std::max_element(c.thermal().temperature().begin(),c.thermal().temperature().end());emit({"phase08_multiphysics","joule_heating_thermal","cpu","element_steps",nx*ny*2U,steps,setup_ms,sim_ms,double(nx*ny*2U)*double(steps),max_t});return 0;}
